    *symmetry_error = INFINITY;
    return ADCS_E_RANGE;
}

if (adcs_quat_normalize(q_bi, &qn) != ADCS_OK) {
    body->m[0][0] = 0.0; body->m[0][1] = 0.0; body->m[0][2] = 0.0;
    body->m[1][0] = 0.0; body->m[1][1] = 0.0; body->m[1][2] = 0.0;
    body->m[2][0] = 0.0; body->m[2][1] = 0.0; body->m[2][2] = 0.0;
    *trace = 0.0;
    *symmetry_error = INFINITY;
    return ADCS_E_RANGE;
}

c_bi = adcs_quat_to_dcm_bi(&qn);
c_bi_t = adcs_mat3_transpose(&c_bi);
tmp = adcs_mat3_mul(&c_bi, inertial);
p_b = adcs_mat3_mul(&tmp, &c_bi_t);

tr = p_b.m[0][0] + p_b.m[1][1] + p_b.m[2][2];
sym = fabs(p_b.m[0][1] - p_b.m[1][0]) +
      fabs(p_b.m[0][2] - p_b.m[2][0]) +
      fabs(p_b.m[1][2] - p_b.m[2][1]);

*body = p_b;
*trace = tr;
*symmetry_error = sym;
return ADCS_OK;
